import { useId, useState, type FormEvent } from 'react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
] as const;

type RoleValue = (typeof ROLES)[number]['value'];

export default function TeamInviteForm() {
  const fieldId = useId();
  const emailId = `${fieldId}-email`;
  const hintId = `${fieldId}-hint`;
  const errorId = `${fieldId}-error`;
  const roleId = `${fieldId}-role`;
  const notifyId = `${fieldId}-notify`;

  const [email, setEmail] = useState('');
  const [role, setRole] = useState<RoleValue>('editor');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !isValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    setTouched(true);
    event.preventDefault();
    if (!isValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  }

  return (
    <section
      className="jx-stack"
      style={{ display: 'grid', gap: 'var(--jx-space-4)', maxWidth: '28rem' }}
    >
      {invited !== null && (
        <div
          className="jx-alert jx-alert--success"
          role="status"
          aria-live="polite"
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: 'var(--jx-space-3)',
            borderRadius: 'var(--jx-radius)',
          }}
        >
          <span style={{ flex: '1 1 auto' }}>
            Приглашение отправлено на {invited}
          </span>
          <button
            type="button"
            className="jx-btn jx-btn--ghost jx-btn--icon"
            aria-label="Закрыть сообщение"
            onClick={() => setInvited(null)}
          >
            ×
          </button>
        </div>
      )}

      <form
        className="jx-card jx-form"
        onSubmit={handleSubmit}
        noValidate
        style={{
          display: 'grid',
          gap: 'var(--jx-space-4)',
          borderRadius: 'var(--jx-radius)',
        }}
      >
        <div className="jx-field" style={{ display: 'grid', gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" htmlFor={emailId}>
            Рабочая почта
          </label>
          <input
            id={emailId}
            className="jx-input"
            type="email"
            name="email"
            autoComplete="email"
            placeholder="name@company.com"
            value={email}
            aria-invalid={showError}
            aria-describedby={showError ? `${hintId} ${errorId}` : hintId}
            onChange={(event) => setEmail(event.target.value)}
            onBlur={() => setTouched(true)}
          />
          <p id={hintId} className="jx-field__hint">
            Приглашение придёт на этот адрес и будет действовать 7 дней.
          </p>
          {showError && (
            <p id={errorId} className="jx-field__error" role="alert">
              Введите корректный адрес, например name@company.com
            </p>
          )}
        </div>

        <div className="jx-field" style={{ display: 'grid', gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" htmlFor={roleId}>
            Роль в команде
          </label>
          <select
            id={roleId}
            className="jx-select"
            name="role"
            value={role}
            onChange={(event) => setRole(event.target.value as RoleValue)}
          >
            {ROLES.map((item) => (
              <option key={item.value} value={item.value}>
                {item.label}
              </option>
            ))}
          </select>
        </div>

        <div
          className="jx-field jx-field--inline"
          style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-3)' }}
        >
          <button
            id={notifyId}
            type="button"
            role="switch"
            aria-checked={notify}
            className="jx-switch"
            onClick={() => setNotify((value) => !value)}
          >
            <span className="jx-switch__track">
              <span className="jx-switch__thumb" />
            </span>
          </button>
          <label className="jx-label" htmlFor={notifyId}>
            Отправить уведомление
          </label>
        </div>

        <button type="submit" className="jx-btn jx-btn--primary" disabled={!isValid}>
          Отправить приглашение
        </button>
      </form>
    </section>
  );
}

